-- ============================================================
-- XingoTech 行政区划模块数据库初始化脚本
-- 数据标准：GB/T 2260（中华人民共和国行政区划代码）
-- 层级：1-省/直辖市/自治区/特别行政区
--       2-地级市/自治州/地区
--       3-市辖区/县级市/县
-- ============================================================

CREATE TABLE IF NOT EXISTS `administrative_division` (
  `id`          VARCHAR(24)  NOT NULL                COMMENT '主键(24位随机十六进制)',
  `code`        VARCHAR(12)  NOT NULL                COMMENT '行政区划代码',
  `name`        VARCHAR(100) NOT NULL                COMMENT '行政区划名称',
  `parent_code` VARCHAR(12)  DEFAULT NULL            COMMENT '父级代码',
  `level`       TINYINT      NOT NULL                COMMENT '层级(1-省,2-市,3-区县)',
  `enabled`     TINYINT      DEFAULT 1               COMMENT '是否启用(1-启用,0-禁用)',
  `created_time` DATETIME    DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` DATETIME    DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_code` (`code`),
  KEY `idx_parent_code` (`parent_code`),
  KEY `idx_level` (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='行政区划表';

